1	import { createBrowserClient } from "@supabase/ssr";
2	import type { Database } from "./types";
3	import type { SupabaseClient } from "@supabase/supabase-js";
4	
5	const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
6	const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
7	
8	/**
9	 * Build a new browser Supabase client. Throws a clear error if the
10	 * required public env vars are missing — but only when actually called,
11	 * not at module-load time. This matters because `next build` evaluates
12	 * every module during the "Collecting page data" phase, and if this
13	 * file threw at module evaluation the entire build would fail on any
14	 * machine without NEXT_PUBLIC_SUPABASE_* set (CI, Docker layer caches,
15	 * etc.). The app is still unusable at runtime without these vars, but
16	 * the build succeeds and surfaces a clean error when the first request
17	 * hits an authenticated route.
18	 */
19	export function createClient(): SupabaseClient<Database> {
20	  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
21	    throw new Error(
22	      "Missing Supabase environment variables. Set NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY in the hosting environment (Railway Variables tab for production, .env.local for local dev).",
23	    );
24	  }
25	  return createBrowserClient<Database>(SUPABASE_URL, SUPABASE_ANON_KEY);
26	}
27	
28	// Lazy singleton. The first caller that touches any property on this
29	// proxy triggers createClient() — so at module-load time during
30	// `next build`, nothing throws and page data collection succeeds.
31	let _supabase: SupabaseClient<Database> | null = null;
32	function getClient(): SupabaseClient<Database> {
33	  if (!_supabase) _supabase = createClient();
34	  return _supabase;
35	}
36	
37	export const supabase = new Proxy({} as SupabaseClient<Database>, {
38	  get(_target, prop) {
39	    const client = getClient();
40	    const value = Reflect.get(client, prop);
41	    // Bind methods so `this` stays correct for chained Supabase calls
42	    return typeof value === "function" ? value.bind(client) : value;
43	  },
44	});
