8	import AuthDialog from "@/components/AuthDialog";
9	import JobDetailView from "@/components/JobDetailView";
10	import JobsOverviewCard from "@/components/JobsOverviewCard";
11	import { Card, CardContent } from "@/components/ui/card";
12	import { Badge } from "@/components/ui/badge";
